<script lang="ts">
 import {Mail,Paperclip,ArrowRight} from '@lucide/svelte';
 import {enter} from './motion';
 import type {Row} from './types';
 let {records,canEdit,busy,onGenerate,onOpen,onMail,onPreview}:{records:Row[];canEdit:boolean;busy:boolean;onGenerate:(r:Row)=>void;onOpen:(id:number)=>void;onMail:(r:Row)=>void;onPreview:(f:Row)=>void}=$props();
 function reveal(node:HTMLElement,index:number){return index<6?enter(node):{destroy(){}}}
 function date(value:string){if(!value)return 'Not entered';const d=new Date(value+'T00:00:00');return Number.isNaN(d.getTime())?value:d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}
</script>
<section class="intimation-queue" aria-labelledby="pending-intimations-title">
 <div class="queue-heading"><div><h3 id="pending-intimations-title">Pending intimations <span>{records.length}</span></h3><p>Review the buyer’s instructions, then prepare the sample indent.</p></div><p class="queue-help">Requests leave this list after MD approval.</p></div>
 <div class="queue-list">{#each records as r,i (r.id)}
 <article use:reveal={i} class="intimation-card" aria-label={'Intimation SR-'+r.id}>
  <header class="intimation-card__header"><div class="intimation-card__identity"><span class="intimation-card__buyer">{r.buyer||r.profile.brand}</span><h4>{r.profile.buyer_style||'Style not entered'}</h4><span class="intimation-card__reference">Submitted by {r.created_by_name||'Not recorded'} · SR-{r.id}</span></div><div class="intimation-card__status"><span>Pending</span><small>{r.status==='Draft'?'Ready to prepare':r.status==='Submitted'?'Awaiting MD approval':r.status}</small></div></header>
  <dl class="intimation-card__details"><div><dt>Sample type</dt><dd>{r.profile.sample_type||'Not entered'}</dd></div><div><dt>Required date</dt><dd>{date(r.profile.buyer_required_date)}</dd></div><div class="intimation-card__sizes"><dt>Size · colour · quantity</dt><dd>{#each r.variants||[] as v}<span>{v.size||'Size pending'} · {v.colour||'Colour pending'} <b>× {v.quantity}</b></span>{/each}</dd></div></dl>
  <footer class="intimation-card__footer"><div class="intimation-card__files"><button type="button" class="attachment mail-button" aria-label={'Read buyer mail: '+(r.profile.email_subject||'No subject provided')} disabled={busy||!r.profile.email_message} title={r.profile.email_subject||'No pasted buyer message'} onclick={()=>onMail(r)}><Mail size={16}/><span>{r.profile.email_subject||'No subject provided'}</span></button>{#each r.files||[] as file}<button type="button" class="attachment" disabled={busy} title={file.name} onclick={()=>onPreview(file)}><Paperclip size={15}/><span>Preview {file.name}</span></button>{/each}</div>{#if canEdit&&['Draft','Changes requested'].includes(r.status)}<button type="button" class="button primary" disabled={busy} onclick={()=>onGenerate(r)}>Generate sample indent <ArrowRight size={16}/></button>{:else}<button type="button" class="button secondary" disabled={busy} onclick={()=>onOpen(r.id)}>View request <ArrowRight size={16}/></button>{/if}</footer>
 </article>{:else}<div class="queue-empty"><h4>All caught up</h4><p>New intimations will appear here with their sample details and buyer instructions.</p></div>{/each}</div>
</section>
